const CORE_FONTS = new Set(FONT_GROUPS[0][1].concat(FONT_GROUPS[FONT_GROUPS.length - 1][1]));
const _fontLoaded = new Set(CORE_FONTS);
// The five house faces are self-hosted, declared in styles.css, and must never
