  const C = CAT_COLOUR[t.cat]; if (!C) return 0;
  let h = 0; for (let i = 0; i < t.id.length; i++) h = (h * 33 + t.id.charCodeAt(i)) >>> 0;
  const mix = STYLE_BY_CAT[t.cat] || STYLE_MIX;
