  const tint = CAT_OFFWHITE[t.cat] || '#fbf6ef';
  const plates = (t.layers || []).filter(l => l.kind === 'rect' && l.props &&
    typeof l.props.fill === 'string' && /^#[0-9a-f]{6}$/i.test(l.props.fill));
  let n = 0;
