const _ctaLin = v => { v /= 255; return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
const _ctaLum = (r, g, b) => 0.2126 * _ctaLin(r) + 0.7152 * _ctaLin(g) + 0.0722 * _ctaLin(b);
