      if (!s.px.length) return true;
      const L = s.px.map(([r, gg, bb]) => _ctaLum(r * (1 - a), gg * (1 - a), bb * (1 - a))).sort((p, q) => p - q);
      const worst = s.light ? L[Math.floor(L.length * 0.9)] : L[Math.floor(L.length * 0.1)];
      return _ctaRatio(s.ink, worst) >= 4.5;
