  if (typeof spec === 'string') spec = TAGLINE_LOOKS[spec] || { name: spec };
  spec = Object.assign({ fill: 'solid', outline: 'none', effect: 'none', scope: 'tagline', plates: 'keep', angle: 90 }, spec || {});
  pal = pal || TAG_FALLBACK;
